const SHIP_STARTUP_CATALOG=Object.freeze(Object.values(SHIP_PROFILE_REGISTRY).map(p=>Object.freeze({
  id:p.id,name:p.identity.shipName,hullNumber:p.identity.hullNumber,revision:p.revision,
  vlsCells:Object.values(p.weapons.vls.sections).reduce((n,s)=>n+s.cells,0),crew:p.crew.roster
})));
let resolveShipStartupSelection=null;
function shipStartupSnapshot(){return {schema:SHIP_STARTUP_SCHEMA,...SHIP_STARTUP_STATE};}
function selectStartupShip(profileId){
  if(SHIP_STARTUP_STATE.phase!=='SELECTING'||typeof profileId!=='string'||!Object.hasOwn(SHIP_PROFILE_REGISTRY,profileId))return false;
  const p=SHIP_PROFILE_REGISTRY[profileId];
  if(!Object.isFrozen(p)||!Object.isFrozen(p.geometry)||!Object.isFrozen(p.weapons))return false;
  SHIP_STARTUP_STATE.phase='INITIALIZING';SHIP_STARTUP_STATE.profileId=p.id;SHIP_STARTUP_STATE.profileRevision=p.revision;
  const button=document.getElementById('aegisShipConfirmBtn');if(button){button.disabled=true;button.textContent='장비 준비 중…';}
  const picker=document.getElementById('aegisShipSelect');if(picker)picker.disabled=true;
  resolveShipStartupSelection(p);resolveShipStartupSelection=null;return true;
}
