    const picker=root.querySelector('#aegisShipSelect'),detail=root.querySelector('#aegisShipSelectionDetail');
    for(const p of SHIP_STARTUP_CATALOG){const option=document.createElement('option');option.value=p.id;option.textContent=[p.hullNumber,p.name].filter(Boolean).join(' · ');picker.appendChild(option);}
    const update=()=>{const p=SHIP_STARTUP_CATALOG.find(q=>q.id===picker.value);detail.textContent=p?`VLS ${p.vlsCells}셀 · 승조원 ${p.crew}명 · 함선을 선택한 뒤 무장 편성을 확정합니다.`:'';};
    picker.addEventListener('change',update);root.querySelector('#aegisShipConfirmBtn').addEventListener('click',()=>selectStartupShip(picker.value));
