window.__AEGIS_SHIP_STARTUP__=Object.freeze({catalog:()=>SHIP_STARTUP_CATALOG.map(q=>({...q})),snapshot:shipStartupSnapshot,select:selectStartupShip});
const ACTIVE_SHIP_PROFILE=await chooseShipBeforeInitialization();
const ACTIVE_SHIP_PROFILE_ID_V48_WIP09=ACTIVE_SHIP_PROFILE.id; // COMPAT_REQUIRED

function completeShipStartup(){
  if(SHIP_STARTUP_STATE.phase!=='INITIALIZING'||SHIP_STARTUP_STATE.initializationCount!==0)throw Error('SHIP_STARTUP_LIFECYCLE');
  // Resolve the existing profile-selected builders once before departure, including
  // dynamics which was previously lazy until the first physical tick.
  getDamageFloodV1();getDamageControlV1();getWaveFloodEnvironmentV48Wip05();
  getShipInteriorTopologyV48Wip06();getShipCrewV21();getShipMassLedgerV32();getShipDynamicsV15();
  const r=ACTIVE_SHIP_RUNTIME,checks=runtimeOwnershipAuditV48Wip11A();
  if(r.profileId!==SHIP_STARTUP_STATE.profileId||r.profileRevision!==SHIP_STARTUP_STATE.profileRevision||!checks.pass)throw Error('SHIP_STARTUP_BINDING_FAILED');
  for(const key of ['mass','dynamics','interior','crew','environment','damage'])if(!r[key])throw Error('SHIP_STARTUP_SUBSYSTEM_MISSING:'+key);
  if(!r.weapons.mainGun||!r.weapons.vls||!r.weapons.closeIn)throw Error('SHIP_STARTUP_WEAPONS_MISSING');
  SHIP_STARTUP_STATE.entityId=r.entityId;SHIP_STARTUP_STATE.initializationCount=1;SHIP_STARTUP_STATE.phase='PREPARING';
  document.getElementById('aegisShipSelectionOverlay')?.remove();return shipStartupSnapshot();
}
function shipStartupCanDepart(){return SHIP_STARTUP_STATE.phase==='PREPARING'&&SHIP_STARTUP_STATE.initializationCount===1&&SHIP_STARTUP_STATE.entityId===ACTIVE_SHIP_RUNTIME.entityId;}
function recordShipDeparture(){SHIP_STARTUP_STATE.phase='DEPARTED';}

function playerShipEntityId(profile){
  const hull=String(profile.identity.hullNumber??profile.id).replace(/[^A-Za-z0-9_]/g,'');
  if(!hull)throw Error('SHIP_IDENTITY_REQUIRED');return 'SHIP_'+hull+'_OWN';
}
// Creation is detached and has no writes to the active world. Subsystems are bound
// in their existing order only after the selected profile has been fixed.
function createPlayerShipSession(profile,options={}){
  if(!profile||!Object.isFrozen(profile))throw Error('IMMUTABLE_SHIP_PROFILE_REQUIRED');
  const runtime=createShipRuntime(profile,{...options,entityId:options.entityId??playerShipEntityId(profile)});
  const engagement={schema:'AEGIS_ENGAGEMENT_RUNTIME_V48_WIP11A',schemaVersion:1,activePlayerShipId:runtime.entityId,ships:new Map([[runtime.entityId,runtime]]),world:{frame:WIP14A_WORLD_FRAME,entities:{aircraft:null,surfaceContacts:null,hostileMissiles:null,asmWreckage:null,ordnance:null,ramOrdnance:null,ciwsProjectiles:null,mainGunProjectiles:null,countermeasures:null,activeDecoys:[]},events:{waterSurface:null,visual:null},presentationEpoch:0},terrain:{islands:null},scenario:null,lifecycle:{revision:0,lastEvent:'CREATED'}};
  return Object.freeze({profile,runtime,engagement});
}
const ACTIVE_SHIP_SESSION=createPlayerShipSession(ACTIVE_SHIP_PROFILE);
const ACTIVE_SHIP_RUNTIME=ACTIVE_SHIP_SESSION.runtime;

const ENGAGEMENT_RUNTIME=ACTIVE_SHIP_SESSION.engagement;

function createProfileVlsInventory(profile){
  const inventory={};
  for(const [section,cfg]of Object.entries(profile.weapons.vls.sections)){
    if(!Number.isInteger(cfg.cells)||cfg.cells<0||!Number.isInteger(cfg.cols)||cfg.cols<1||!Number.isInteger(cfg.rows)||cfg.rows<1||cfg.cells>cfg.rows*cfg.cols)throw Error('VLS_SECTION_INVALID:'+section);
    const types=[];
    for(const row of cfg.defaultLoadout){
      if(!['SM2','SM2ER','SM6','ESSM4','EMPTY'].includes(row.type)||!Number.isInteger(row.cells)||row.cells<0)throw Error('VLS_LOADOUT_INVALID:'+section);
      for(let i=0;i<row.cells;i++)types.push(row.type);
    }
    if(types.length!==cfg.cells)throw Error('VLS_LOADOUT_CAPACITY:'+section);
    inventory[section]=types.map((type,i)=>wip125MakeVlsCell(type,Math.floor(i/cfg.cols),i%cfg.cols));
  }
  return inventory;
}
